//! 🧱️ Actual tuple children retain source, output and partial heap across finite work slices.
use semio_framework_value_retained_clone::*;
#[path="../../../🧪️tests/⏱️effect/🦀️.rs"]
mod effect;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn account(p:RetainedCloneProgress,work:u128,heap:(usize,usize),g:RetainedCloneGrant,totals:&mut(usize,usize),fuel:&mut u128){assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));*fuel=fuel.checked_sub(work).expect("same finite original tuple test treasury");totals.0+=heap.0;totals.1+=heap.1;}
fn open<T:RetainedClone>(make:fn()->T,totals:&mut(usize,usize),fuel:&mut u128)->RetainedCloneSource<T>{let(value,heap)=observe(make);totals.0+=heap.0;totals.1+=heap.1;let(mut birth,heap)=observe(||RetainedCloneSource::<T>::admission_owned(value,()));assert_eq!(heap,(0,0));let mut out=None;for _ in 0..1024{if birth.terminal_is_empty(){break}let g=grant(birth.next_demand().unwrap());let mut actual=None;let(turn,heap)=observe(||if birth.phase()=="ready"{birth.take_output(&mut out,g)}else{effect::with_effect(g,effect::CPU,&mut actual,|e|birth.advance(e)).0});if let Some(bytes)=actual{assert_eq!(bytes,heap.0)}let work=turn.work;let step=turn.result.unwrap();account(step.progress(),work,heap,g,totals,fuel);}assert!(birth.terminal_is_empty());out.unwrap()}
fn close_value<T:RetainedClone>(value:T,totals:&mut(usize,usize),fuel:&mut u128){let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..10000{if value.is_none()&&close.is_empty(){break}let g=grant(close.next_owner_demands::<T>(value.is_some(),&None,4096).unwrap());let(turn,heap)=observe(||if close.is_empty(){let t=effect::begin_granted(&mut close,&mut value,g);semio_framework_value_retained_clone::RetainedWorkOutcome{result:t.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:t.work}}else{effect::step_granted(&mut close,g)});let work=turn.work;account(turn.result.unwrap().progress(),work,heap,g,totals,fuel);}assert!(value.is_none()&&close.is_empty());}
fn exercise<T:RetainedClone+PartialEq+std::fmt::Debug>(make:fn()->T,count:usize,cancel:bool){let mut totals=(0,0);let mut fuel=1000000;let mut source=open(make,&mut totals,&mut fuel);let mut foreign=open(make,&mut totals,&mut fuel);let original=source.borrow().get()as*const T;let(mut cursor,heap)=observe(T::retained_clone_cursor);assert_eq!(heap,(0,0));let mut advanced=0;let mut complete=false;
 for turn in 0..1000{let max_work=if advanced<4{3}else{64};let d=cursor.advance_demands(source.borrow(),4096,max_work).unwrap();let q=cursor.advance_work_demand(source.borrow(),4096,max_work).unwrap();assert!(q<=max_work);let low=cursor.advance_work_demand(source.borrow(),4096,1).unwrap();assert!(low<=1);if low==0{let g=grant(cursor.advance_demands(source.borrow(),4096,1).unwrap());let(t,h)=observe(||effect::advance(&mut cursor,source.borrow(),4096,1,g));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}let mut g=grant(d);g.maximum_items=1;let(denied,heap)=observe(||effect::advance(&mut cursor,source.borrow(),4096,0,g));assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));let(t,heap)=observe(||effect::advance(&mut cursor,source.borrow(),4096,max_work,g));assert!(t.work<=u128::from(max_work)&&t.work<=u128::from(q));let work=t.work;let step=t.result.unwrap();account(step.progress(),work,heap,g,&mut totals,&mut fuel);assert_eq!(source.borrow().get()as*const T,original);
 if work>0{advanced+=1}if advanced==1{let(t,heap)=observe(||effect::advance(&mut cursor,foreign.borrow(),4096,64,g));assert!(t.result.is_err());assert_eq!(t.work,0);assert_eq!(heap,(0,0));}if advanced==4{assert!(!cursor.output_ready());if cancel{break}}
 if matches!(step,RetainedCloneStep::Complete(_)){assert!(cursor.output_ready());assert_eq!(work,1,"the completing tuple turn performs only its own assembly; child takes are earlier turns");assert_eq!(step.progress().copied_items,1);complete=true;break}assert!(turn<999);}
 assert_eq!(complete,!cancel);if complete{let g=grant(cursor.take_demand().unwrap());let take_work=cursor.take_work_demand().unwrap();let(t,heap)=observe(||effect::take(&mut cursor,g));assert_eq!(t.work,u128::from(take_work));let(value,p)=t.result.unwrap().unwrap();account(p,t.work,heap,g,&mut totals,&mut fuel);assert_eq!(&value,source.borrow().get());close_value(value,&mut totals,&mut fuel);}
 let q=cursor.begin_close_work_demand().unwrap();let(t,heap)=observe(||{let g=grant(cursor.begin_close_demand().unwrap());effect::begin_close_paid(&mut cursor,g)});assert_eq!(t.work,u128::from(q));t.result.unwrap();assert_eq!(heap,(0,0));fuel=fuel.checked_sub(t.work).unwrap();for turn in 0..10000{if cursor.terminal_is_empty(){break}let d=cursor.close_demands(4096).unwrap();let g=grant(d);let q=cursor.close_work_demand(4096).unwrap();let(t,heap)=observe(||effect::close_step(&mut cursor,g));assert!(t.work<=u128::from(q));let work=t.work;account(t.result.unwrap().progress(),work,heap,g,&mut totals,&mut fuel);assert!(turn<9999)}assert!(cursor.terminal_is_empty());assert_eq!(observe(||drop(cursor)).1,(0,0));
 for s in[&mut source,&mut foreign]{for turn in 0..10000{if s.terminal_is_empty(){break}let g=grant(s.next_close_demand(4096).unwrap());let(t,heap)=observe(||effect::settle(g,|e|s.close_step(e)));let work=t.work;account(t.result.unwrap().progress(),work,heap,g,&mut totals,&mut fuel);assert!(turn<9999)}assert!(s.terminal_is_empty());}assert_eq!(observe(||drop((source,foreign))).1,(0,0));assert_eq!(totals.0,totals.1);
}
#[test]fn actual_tuple_zero_work_partial_child_foreign_source_and_paid_cancel_or_output(){for cancel in[false,true]{exercise(||("abcde".to_owned(),"xy".to_owned()),2,cancel);exercise(||("abcde".to_owned(),"xy".to_owned(),"z".to_owned()),3,cancel);}}
